#!/usr/bin/env bash
# The default-options test. features.yml runs only the scenarios
# (--skip-autogenerated): this feature has no default pins, so installing it
# with its defaults fails by design and this script is not reached there. It
# is kept for a local run that supplies a pin through the image (for example
# `devcontainer features test -f cli-valkey -i <image with CLI_VALKEY_* ENV>`).
set -e

# shellcheck source=/dev/null
source dev-container-features-test-lib
# shellcheck source=valkey-checks.sh
source "$(dirname "$0")/valkey-checks.sh"

check "valkey-cli resolves to /usr/local/bin/valkey-cli" _valkey_cli_is_local_bin
check "valkey-cli is mode 0755, owned by root" _valkey_cli_mode_owner
check "valkey-cli --version runs" valkey-cli --version

reportResults
